\section{Lower Bounds for Denominators of Simple Continued Fraction}
Tags: Simple Continued Fractions

\begin{theorem}
Let $n \in \N \cup \{\infty\}$ be an extended natural number.
Let $\left[{a_0, a_1, a_2, \ldots}\right]$ be a simple continued fraction in $\R$ of length $N$.
Let $q_0, q_1, q_2, \ldots$ be its denominators.
\end{theorem}

\begin{proof}
By Denominators of Simple Continued Fraction are Strictly Increasing, with the possible exception of $1 = q_0 = q_1$, the sequence $\left \langle {q_n}\right \rangle$ is strictly increasing.
Now, since $q_2 > q_1 \ge q_0 = 1$, we have $q_2 \geq 2$.
Then $q_{k+1} \ge q_k + q_{k-1}$ shows that from $q_3$ onwards, the $q_k$s increase in steps of at least $2$.
As $q_3 \ge 3$, it follows that $q_4 \ge 5$.
The result follows.
{{qed}}
Category:Simple Continued Fractions
\end{proof}

\section{Even Convergent of Simple Continued Fraction is Strictly Smaller than Odd Convergent}
Tags: Continued Fractions

\begin{theorem}
Let $n \in \N \cup \set \infty$ be an extended natural number.
Let $\sqbrk {a_0, a_1, \ldots}$ be a simple continued fraction in $\R$ of length $n$.
Let $p_0, p_1, p_2, \ldots$ and $q_0, q_1, q_2, \ldots$ be its numerators and denominators.
Let $\sequence {C_0, C_1, \ldots}$ be its sequence of convergents.
Every even convergent is strictly smaller than every odd convergent.
\end{theorem}

\begin{proof}
Let $k \ge 1$.
From Denominators of Simple Continued Fraction are Strictly Positive, $q_k q_{k - 1}>0$.
From Difference between Adjacent Convergents of Simple Continued Fraction:
:$C_k - C_{k - 1} = \dfrac {\paren {-1}^{k + 1} } {q_k q_{k - 1} }$
Let $k$ be even.
Then:
:$\exists s \in \N: k = 2 s$
and:
:$C_{2 s} < C_{2 s - 1}$
Let $k$ be odd.
Then:
:$\exists t \in \N: k = 2 t + 1$
and:
:$C_{2 t + 1 } > C_{2 t}$
Now, consider any even convergent $C_{2 s}$ and any odd convergent $C_{2 t + 1}$, with $s, t \ge 0$.
If $2 s < 2 t + 1$, then $2 s \le 2 t$, so:
{{begin-eqn}}
{{eqn | l = C_{2 s}
      | o = \le
      | r = C_{2 t}
      | c = Even Convergents of Simple Continued Fraction are Strictly Increasing
}}
{{eqn | o = <
      | r = C_{2 t + 1}
      | c = by the above
}}
{{end-eqn}}
If $2 s > 2 t + 1$, then $2 s - 1 \ge 2 t + 1$, so:
{{begin-eqn}}
{{eqn | l = C_{2 s}
      | o = <
      | r = C_{2 s - 1}
      | c = by the above
}}
{{eqn | o = \le
      | r = C_{2 t + 1}
      | c = Odd Convergents of Simple Continued Fraction are Strictly Decreasing
}}
{{end-eqn}}
In either case:
:$C_{2 s} < C_{2 t + 1}$
Hence the result.
{{qed}}
\end{proof}

\section{Even Convergents of Simple Continued Fraction are Strictly Increasing}
Tags: Simple Continued Fractions

\begin{theorem}
Let $n \in \N \cup \set \infty$ be an extended natural number.
Let $\sqbrk {a_0, a_1, \ldots}$ be a simple continued fraction in $\R$ of length $n$.
Let $p_0, p_1, p_2, \ldots$ and $q_0, q_1, q_2, \ldots$ be its numerators and denominators.
Let $\sequence {C_0, C_1, \ldots}$ be its sequence of convergents.
The even convergents satisfy $C_0 < C_2 < C_4 \cdots$.
\end{theorem}

\begin{proof}
Let $k \ge 2$ be an even integer.
From Difference between Adjacent Convergents But One of Simple Continued Fraction:
:$C_k - C_{k - 2} = \dfrac {\paren {-1}^k a_k} {q_k q_{k - 2} } = \dfrac {a_k} {q_k q_{k - 2} }$
By definition of simple continued fraction, $a_k > 0$.
By Convergents of Simple Continued Fraction are Rationals in Canonical Form, $q_k > 0$ and $q_{k - 2} > 0$.
Thus $C_k > C_{k - 2}$.
{{qed}}
\end{proof}

