\section{Moment Generating Function of Beta Distribution}
Tags: Beta Distribution, Moment Generating Functions

\begin{theorem}
Let $X \sim \BetaDist \alpha \beta$ denote the Beta distribution fior some $\alpha, \beta > 0$.
Then the moment generating function $M_X$ of $X$ is given by: 
:$\ds \map {M_X} t = 1 + \sum_{k \mathop = 1}^\infty \paren {\prod_{r \mathop = 0}^{k - 1} \frac {\alpha + r} {\alpha + \beta + r} } \frac {t^k} {k!}$
\end{theorem}

\begin{proof}
From the definition of the Beta distribution, $X$ has probability density function:
:$\map {f_X} x = \dfrac {x^{\alpha - 1} \paren {1 - x}^{\beta - 1} } {\map \Beta {\alpha, \beta} }$
From the definition of a moment generating function:
:$\ds \map {M_X} t = \expect {e^{t X} } = \int_0^1 e^{t x} \map {f_X} x \rd x$
So:
{{begin-eqn}}
{{eqn	| l = \map {M_X} t
	| r = \frac 1 {\map \Beta {\alpha, \beta} } \int_0^1 e^{t x} x^{\alpha - 1} \paren {1 - x}^{\beta - 1} \rd x
}}
{{eqn	| r = \frac 1 {\map \Beta {\alpha, \beta} } \int_0^1 \paren {\sum_{k \mathop = 0}^\infty \frac {\paren {t x}^k} {k!} } x^{\alpha - 1} \paren {1 - x}^{\beta - 1} \rd x
	| c = Power Series Expansion for Exponential Function
}}
{{eqn	| r = \frac 1 {\map \Beta {\alpha, \beta} } \sum_{k \mathop = 0}^\infty \frac {t^k} {k!} \int_0^1 x^{\alpha + k - 1} \paren {1 - x}^{\beta - 1} \rd x
	| c = Power Series is Termwise Integrable within Radius of Convergence
}}
{{eqn	| r = \sum_{k \mathop = 0}^\infty \frac{t^k} {k!} \paren {\frac {\map \Beta {\alpha + k, \beta} } {\map \Beta {\alpha, \beta} } }
	| c = {{Defof|Beta Function/Definition 1|Beta Function}}
}}
{{eqn	| r = \frac {\map \Beta {\alpha, \beta} } {\map \Beta {\alpha, \beta} } \frac {t^0} {0!} + \sum_{k \mathop = 1}^\infty \frac{t^k} {k!} \paren {\frac {\map \Beta {\alpha + k, \beta} } {\map \Beta {\alpha, \beta} } }
}}
{{eqn	| r = 1 + \sum_{k \mathop = 1}^\infty \paren {\frac {\map \Gamma {\alpha + k} \map \Gamma \beta} {\map \Gamma {\alpha + \beta + k} } \cdot \frac {\map \Gamma {\alpha + \beta} } {\map \Gamma \alpha \map \Gamma \beta} } \frac{t^k} {k!}
	| c = {{Defof|Beta Function|index = 3|Beta Function}}
}}
{{eqn	| r = 1 + \sum_{k \mathop = 1}^\infty \paren {\frac {\map \Gamma {\alpha + k} } {\map \Gamma \alpha} \cdot \frac {\map \Gamma {\alpha + \beta} } {\map \Gamma {\alpha + \beta + k} } } \frac{t^k} {k!}
}}
{{eqn	| r = 1 + \sum_{k \mathop = 1}^\infty \paren {\frac {\map \Gamma \alpha \prod_{r \mathop = 0}^k \paren {\alpha + r} } {\map \Gamma \alpha} \cdot \frac {\map \Gamma {\alpha + \beta} } {\map \Gamma {\alpha + \beta} \prod_{r \mathop = 0}^k \paren {\alpha + \beta + r} } } \frac{t^k} {k!}
	| c = Gamma Difference Equation
}}
{{eqn	| r = 1 + \sum_{k \mathop = 1}^\infty \paren {\prod_{r \mathop = 0}^{k - 1} \frac {\alpha + r} {\alpha + \beta + r} } \frac{t^k} {k!}
	| c = Product of Products
}}
{{end-eqn}}
{{qed}}
Category:Moment Generating Functions
Category:Beta Distribution
\end{proof}

\section{Moment Generating Function of Continuous Uniform Distribution}
Tags: Uniform Distribution, Moment Generating Functions, Continuous Uniform Distribution

\begin{theorem}
Let $X \sim \ContinuousUniform a b$ for some $a, b \in \R$ denote the continuous uniform distribution on the interval $\closedint a b$.
Then the moment generating function of $X$ is given by: 
:$\map {M_X} t = \begin {cases} \dfrac {e^{t b} - e^{t a} } {t \paren {b - a} } & t \ne 0 \\ 1 & t = 0 \end{cases}$
\end{theorem}

\begin{proof}
From the definition of the continuous uniform distribution, $X$ has probability density function: 
:$\map {f_X} x = \begin{cases} \dfrac 1 {b - a} & a \le x \le b \\ 0 & \text{otherwise} \end{cases}$
From the definition of a moment generating function:
:$\ds \map {M_X} t = \expect {e^{t X} } = \int_{-\infty}^\infty e^{t x} \map {f_X} x \rd x$
where $\expect \cdot$ denotes expectation.
First, consider the case $t \ne 0$. 
Then: 
{{begin-eqn}}
{{eqn	| l = \map {M_X} t
	| r = \int_{-\infty}^a 0 e^{t x} \rd x + \int_a^b \frac{ e^{t x} } {b - a} \rd x + \int_b^\infty 0 e^{t x} \rd x
}}
{{eqn	| r = \intlimits {\frac {e^{t x} } {t \paren {b - a} } } a b
	| c = Primitive of $e^{a x}$, Fundamental Theorem of Calculus
}}
{{eqn	| r = \frac {e^{t b} - e^{t a} } {t \paren {b - a} }
}}
{{end-eqn}}
In the case $t = 0$, we have $\expect {X^0} = \expect 1 = 1$. 
{{qed}}
Category:Moment Generating Functions
Category:Continuous Uniform Distribution
\end{proof}

\section{Moment Generating Function of Exponential Distribution}
Tags: Exponential Distribution, Moment Generating Functions

\begin{theorem}
Let $X$ be a continuous random variable with an exponential distribution with parameter $\beta$ for some $\beta \in \R_{> 0}$.
Then the moment generating function $M_X$ of $X$ is given by: 
:$\ds \map {M_X} t = \frac 1 {1 - \beta t}$
for $t < \dfrac 1 \beta$, and is undefined otherwise.
\end{theorem}

\begin{proof}
From the definition of the Exponential distribution, $X$ has probability density function:
:$\ds \map {f_X} x = \frac 1 \beta e^{-\frac x \beta}$
From the definition of a moment generating function:
:$\ds \map {M_X} t = \expect {e^{t X} } = \int_0^\infty e^{t x} \map {f_X} x \rd x$
Then: 
{{begin-eqn}}
{{eqn	| l = \map {M_X} t
	| r = \frac 1 \beta \int_0^\infty e^{x \paren {-\frac 1 \beta + t} } \rd x
	| c = Exponential of Sum
}}
{{eqn	| r = \frac 1 {\beta \paren {-\frac 1 \beta + t} } \sqbrk {e^{x \paren {-\frac 1 \beta + t} } }_0^\infty
	| c = Primitive of Exponential Function
}}
{{end-eqn}}
Note that if $t > \dfrac 1 \beta$, then $\ds e^{x \paren {-\frac 1 \beta + t} } \to \infty$ as $x \to \infty$ by Exponential Tends to Zero and Infinity, so the integral diverges in this case. 
If $t = \dfrac 1 \beta$ then the integrand is identically $1$, so the integral similarly diverges in this case. 
If $t < \dfrac 1 \beta$, then $\ds e^{x \paren {-\frac 1 \beta + t} } \to 0$ as $x \to \infty$ from Exponential Tends to Zero and Infinity, so the integral converges in this case. 
Therefore, the function is only well defined for $t < \dfrac 1 \beta$.
Proceeding:
{{begin-eqn}}
{{eqn	| l = \frac 1 {\beta \paren {-\frac 1 \beta + t} } \sqbrk {e^{x \paren {-\frac 1 \beta + t} } }_0^\infty
	| r = \frac 1 {\beta \paren {-\frac 1 \beta + t} } \paren {0 - 1}
	| c = Exponential Tends to Zero and Infinity, Exponential of Zero
}}
{{eqn	| r = \frac 1 {\beta \paren {\frac 1 \beta - t} }
}}
{{eqn	| r = \frac 1 {1 - \beta t}
}}
{{end-eqn}}
{{qed}}
Category:Moment Generating Functions
Category:Exponential Distribution
\end{proof}

\section{Moment Generating Function of Gamma Distribution}
Tags: Moment Generating Function of Gamma Distribution, Moment Generating Functions, Gamma Distribution

\begin{theorem}
Let $X \sim \map \Gamma {\alpha, \beta}$ for some $\alpha, \beta > 0$, where $\Gamma$ is the Gamma distribution.
Then the moment generating function of $X$ is given by: 
:$\map {M_X} t = \begin {cases} \paren {1 - \dfrac t \beta}^{-\alpha} & t < \beta \\ \text {does not exist} & t \ge \beta \end {cases}$
\end{theorem}

\begin{proof}
From the definition of the Gamma distribution, $X$ has probability density function:
:$\map {f_X} x = \dfrac {\beta^\alpha x^{\alpha - 1} e^{-\beta x} } {\map \Gamma \alpha}$
From the definition of a moment generating function:
:$\ds \map {M_X} t = \expect {e^{t X} } = \int_0^\infty e^{t x} \map {f_X} x \rd x$
First take $t < \beta$. 
Then:
{{begin-eqn}}
{{eqn	| l = \map {M_X} t
	| r = \frac {\beta^\alpha} {\map \Gamma \alpha} \int_0^\infty x^{\alpha - 1} e^{-\paren {\beta - t} x} \rd x
}}
{{eqn	| r = \frac {\beta^\alpha} {\map \Gamma \alpha} \int_0^\infty \paren {\frac u {\beta - t} }^{\alpha - 1} e^{-u} \frac {\rd u} {\beta - t}
	| c = substituting $\paren {\beta - t} x = u$
}}
{{eqn	| r = \frac {\beta^\alpha} {\map \Gamma \alpha \paren {\beta - t}^\alpha} \int_0^\infty u^{\alpha - 1} e^{-u}  \rd u
}}
{{eqn	| r = \frac {\beta^\alpha \map \Gamma \alpha} {\map \Gamma \alpha \paren {\beta - t}^\alpha}
	| c = {{Defof|Gamma Function}}
}}
{{eqn	| r = \paren {\frac \beta {\beta - t} }^\alpha
}}
{{eqn	| r = \paren {\frac {\beta - t} \beta}^{-\alpha}
}}
{{eqn	| r = \paren {1 - \frac t \beta}^{-\alpha}
}}
{{end-eqn}}
{{qed|lemma}}
Now take $t = \beta$. 
Our integral becomes: 
{{begin-eqn}}
{{eqn 	| l = \frac {\beta^\alpha} {\map \Gamma \alpha} \int_0^\infty x^{\alpha - 1} \rd x
	| r = \frac {\beta^\alpha} {\alpha \map \Gamma \alpha} \bigintlimits {x^\alpha} 0 \infty
	| c = Primitive of Power, Fundamental Theorem of Calculus
}}
{{eqn	| r = 0 + \frac {\beta^\alpha} {\alpha \map \Gamma \alpha} \lim_{x \mathop \to \infty} x^\alpha
}}
{{eqn	| o = \to
	| r = \infty
	| c = for $\alpha > 0$, $x^\alpha$ increases without bound as $x \mathop \to \infty$
}}
{{end-eqn}}
So $\expect {e^{\beta X} }$ does not exist.
{{qed|lemma}}
Finally take $t > \beta$.
We have that $-\paren {\beta - t}$ is positive.
As a consequence of Exponential Dominates Polynomial, we have:
:$x^{\alpha - 1} < e^{-\paren {\beta - t} x}$
for sufficiently large $x$. 
Therefore, in this case, the integrand increases without bound. 
We conclude that the integral is divergent.
Hence $\expect {e^{t X} }$ does not exist for $t > \beta$. 
{{qed}}
\end{proof}

\section{Median of Continuous Uniform Distribution}
Tags: Uniform Distribution, Continuous Uniform Distribution

\begin{theorem}
Let $X$ be a continuous random variable which is uniformly distributed on a closed real interval $\closedint a b$. 
Then the median $M$ of $X$ is given by: 
:$M = \dfrac {a + b} 2$
\end{theorem}

\begin{proof}
From the definition of the continuous uniform distribution, $X$ has probability density function:
:$\map {f_X} x = \dfrac 1 {b - a}$
Note that $f_X$ is non-zero, so the median is unique. 
We have by the definition of a median: 
:$\ds \map \Pr {X < M} = \frac 1 {b - a} \int_a^M \rd x = \frac 1 2$
We have, by Primitive of Constant: 
:$\dfrac {M - a} {b - a} = \dfrac 1 2$
So: 
{{begin-eqn}}
{{eqn	| l = M
	| r = a + \frac {b - a} 2
}}
{{eqn	| r = \frac {b - a + 2 a} 2
}}
{{eqn	| r = \frac {b + a} 2
}}
{{end-eqn}}
{{qed}}
Category:Continuous Uniform Distribution
\end{proof}

\section{Median of Exponential Distribution}
Tags: Exponential Distribution

\begin{theorem}
Let $X$ be a continuous random variable of the exponential distribution with parameter $\beta$ for some $\beta \in \R_{> 0}$. 
Then the median of $X$ is equal to $\beta \ln 2$.
\end{theorem}

\begin{proof}
Let $M$ be the median of $X$.
From the definition of the exponential distribution, $X$ has probability density function: 
:$\map {f_X} x = \dfrac 1 \beta e^{-\frac x \beta}$
Note that $f_X$ is non-zero, so the median is unique. 
We have by the definition of a median: 
:$\ds \map \Pr {X < M} = \frac 1 \beta \int_0^M e^{-\frac x \beta} \rd x = \frac 1 2$
Evaluating this integral:
{{begin-eqn}}
{{eqn	| l = \frac 1 \beta \int_0^M e^{-\frac x \beta} \rd x
	| r = \frac 1 \beta \sqbrk {-\beta e^{-\frac x \beta} }_0^M
	| c = Primitive of Exponential Function
}}
{{eqn	| r = 1 - e^{-\frac M \beta}
}}
{{end-eqn}}
So: 
:$1 - e^{-\frac M \beta} = \dfrac 1 2$
Then: 
:$e^{-\frac M \beta} = \dfrac 1 2$
giving: 
:$-\dfrac M \beta = \map \ln {\dfrac 1 2}$
So, by Logarithm of Reciprocal: 
:$M = \beta \ln 2$
{{qed}}
Category:Exponential Distribution
\end{proof}

\section{Exponential Distribution in terms of Beta Distribution}
Tags: Exponential Distribution, Beta Distribution

\begin{theorem}
Let $\sequence {X_n}$ be a sequence of independent random variables with:
:$X_n \sim \BetaDist 1 n$
for each natural number $n$, where $\BetaDist 1 n$ denotes the beta distribution with parameters $1$ and $n$. 
Then: 
:$n X_n \xrightarrow d X$
with:
:$X \sim \Exponential 1$
where: 
:$\Exponential 1$ denotes the exponential distribution with parameter $1$,
:$\xrightarrow d$ denotes convergence in distribution.
\end{theorem}

\begin{proof}
We aim to show that for each real $x > 0$, we have: 
:$\ds \lim_{n \mathop \to \infty} \map \Pr {X_n \le x} = \map \Pr {X \le x}$
From the definition of the exponential distribution, we have: 
:$\map \Pr {X \le x} = 1 - e^{-x}$
Note that, from the definition of the beta distribution:
:$0 \le X_n \le 1$
So, if $n \le x$, we have: 
:$\map \Pr {X_n \le x} = 1$
Take $n \ge x$. 
Then, we have: 
{{begin-eqn}}
{{eqn	| l = \map \Pr {n X_n \le x}
	| r = \map \Pr {X_n \le \frac x n}
}}
{{eqn	| r = \int_0^{\frac x n} \frac {t^{1 - 1} \paren {1 - t}^{n - 1} } {\map \Beta {1, n} } \rd t
	| c = {{Defof|Beta Distribution}}
}}
{{eqn	| r = \int_0^{\frac x n} \frac {\paren {1 - t}^{n - 1} } {\frac {\map \Gamma 1 \map \Gamma n} {\map \Gamma {n + 1} } } \rd t
	| c = {{Defof|Beta Function/Definition 3|Beta Function}}
}}
{{eqn	| r = \int_0^{\frac x n} \frac {\paren {1 - t}^{n - 1} } {\frac {\map \Gamma n} {n \map \Gamma n} } \rd t
	| c = Gamma Difference Equation
}}
{{eqn	| r = \int_0^{\frac x n} n \paren {1 - t}^{n - 1} \rd t
}}
{{eqn	| r = \intlimits {-\paren {1 - t}^n} 0 {\frac x n}
	| c = Primitive of Power
}}
{{eqn	| r = 1 - \paren {1 - \frac x n}^n
}}
{{end-eqn}}
From the definition of the exponential function as a sequence, we have:
:$\ds \lim_{n \mathop \to \infty} \paren {1 - \frac x n}^n = e^{-x}$
so:
:$\ds \lim_{n \mathop \to \infty} \paren {1 - \paren {1 - \frac x n}^n} = 1 - e^{-x} = \map \Pr {X \le x}$
That is: 
:$\ds \lim_{n \mathop \to \infty} \map \Pr {X_n \le x} = \map \Pr {X \le x}$
as required.
{{qed}}
Category:Exponential Distribution
Category:Beta Distribution
\end{proof}

\section{Exponential Distribution in terms of Continuous Uniform Distribution}
Tags: Exponential Distribution, Continuous Uniform Distribution

\begin{theorem}
Let $X \sim \mathrm U \hointl 0 1$ where $\mathrm U \hointl 0 1$ is the continuous uniform distribution on $\hointl 0 1$.
Let $\beta$ be a positive real number.
Then: 
:$-\beta \ln X \sim \Exponential \lambda$
where $\Exponential \cdot$ is the exponential distribution.
\end{theorem}

\begin{proof}
Let $Y \sim \Exponential \lambda$.
We aim to show that:
:$\map \Pr {Y < -\beta \ln x} = \map \Pr {X > x}$
for all $x \in \hointl 0 1$.
We have:
{{begin-eqn}}
{{eqn	| l = \map \Pr {Y < -\beta \ln x}
	| r = \frac 1 \beta \int_0^{-\beta \ln x} \map \exp {-\frac u \beta} \rd u
	| c = {{Defof|Exponential Distribution}}
}}
{{eqn	| r = \intlimits {-\map \exp {-\frac u \beta} } 0 {-\beta \ln x}
	| c = Primitive of $\exp a x$
}}
{{eqn	| r = -\map \exp {-\frac {-\beta \ln x} {\beta} } + \map \exp 0
}}
{{eqn	| r = 1 - x
	| c = {{Defof|Natural Logarithm}}, Exponential of Zero
}}
{{eqn	| r = \frac 1 {1 - 0} \int_x^1 \rd u
	| c = Primitive of Constant
}}
{{eqn	| r = \map \Pr {X > x}
	| c = {{Defof|Continuous Uniform Distribution}}
}}
{{end-eqn}}
{{qed}}
Category:Exponential Distribution
Category:Continuous Uniform Distribution
\end{proof}

\section{Exponential of Negative of Exponential Random Variable has Beta Distribution}
Tags: Exponential Distribution, Beta Distribution

\begin{theorem}
Let $\beta$ be a positive real number.
Let $X \sim \Exponential \beta$ where $\Exponential \beta$ is the exponential distribution with parameter $\beta$. 
Then:
:$e^{-X} \sim \BetaDist {\dfrac 1 \beta} 1$
\end{theorem}

\begin{proof}
Note that if:
:$Y \sim \BetaDist {\dfrac 1 \beta} 1$
then the probability density function of $Y$, $f_Y$ is given by:
{{begin-eqn}}
{{eqn	| l = \map {f_Y} y
	| r = \frac {y^{\frac 1 \beta - 1} \paren {1 - y}^{1 - 1} } {\map \Beta {\frac 1 \beta, 1} }
	| c = {{Defof|Beta Distribution}}
}}
{{eqn	| r = \frac {y^{\frac 1 \beta - 1} } {\frac {\map \Gamma {\frac 1 \beta} \map \Gamma 1} {\map \Gamma {\frac 1 \beta + 1} } }
	| c = {{Defof|Beta Function}}
}}
{{eqn	| r = \frac 1 {\frac {\map \Gamma {\frac 1 \beta} } {\frac 1 \beta \map \Gamma {\frac 1 \beta} } } y^{\frac 1 \beta}
	| c = Gamma Difference Equation
}}
{{eqn	| r = \frac 1 \beta y^{\frac 1 \beta}
}}
{{end-eqn}}
for each $y > 0$. 
Let:
:$Z = e^{-X}$
It suffices to show that $Z$ has the same probability density function as $Y$.
We have: 
{{begin-eqn}}
{{eqn	| l = \map \Pr {Z \le z}
	| r = \map \Pr {e^{-X} \le z}
}}
{{eqn	| r = \map \Pr {-X \le \ln z}
}}
{{eqn	| r = \map \Pr {X \ge -\ln z}
}}
{{eqn	| r = \map \exp {-\frac {-\ln z} {\beta} }
	| c = {{Defof|Exponential Distribution}}
}}
{{eqn	| r = z^{\frac 1 \beta}
}}
{{end-eqn}}
By Derivative of Power, the probability density function of $Z$, $f_Z$ is therefore given by: 
:$\map {f_Z} z = \dfrac 1 \beta z^{\frac 1 \beta - 1}$
for each $z > 0$.
So:
:$f_Y = f_Z$
{{qed}}
Category:Exponential Distribution
Category:Beta Distribution
\end{proof}

\section{Expectation of Beta Distribution}
Tags: Expectation of Beta Distribution, Beta Distribution, Expectation

\begin{theorem}
Let $X \sim \BetaDist \alpha \beta$ for some $\alpha, \beta > 0$, where $\operatorname{Beta}$ denotes the beta distribution. 
Then:
:$\expect X = \dfrac \alpha {\alpha + \beta}$
\end{theorem}

\begin{proof}
From the definition of the Beta distribution, $X$ has probability density function:
:$\displaystyle f_X \left({x}\right) = \frac { x^{\alpha - 1} \left({1 - x}\right)^{\beta - 1} } {\Beta \left({\alpha, \beta}\right)}$
From the definition of the expected value of a continuous random variable: 
:$\displaystyle \mathbb E \left[{X}\right] = \int_0^1 x f_X \left({x}\right) \rd x$
So:
{{begin-eqn}}
{{eqn	| l = \mathbb E \left[{X}\right]
	| r = \frac 1 {\Beta \left({\alpha, \beta}\right)} \int_0^1 x^\alpha \left({1 - x}\right)^{\beta - 1} \rd x
}}
{{eqn	| r = \frac {\Beta \left({\alpha + 1, \beta}\right)} {\Beta \left({\alpha, \beta}\right)} 
	| c = {{Defof|Beta Function/Definition 1|Beta Function}}
}}
{{eqn	| r = \frac {\Gamma \left({\alpha + 1}\right) \Gamma \left({\beta}\right)} {\Gamma \left({\alpha + \beta + 1}\right)} \cdot \frac {\Gamma \left({\alpha + \beta}\right)} {\Gamma \left({\alpha}\right) \Gamma \left({\beta}\right)}
	| c = {{Defof|Beta Function/Definition 3|Beta Function}}
}}
{{eqn	| r = \frac \alpha {\alpha + \beta} \cdot \frac {\Gamma \left({\alpha}\right) \Gamma \left({\beta}\right) \Gamma \left({\alpha + \beta}\right)} {\Gamma \left({\alpha}\right) \Gamma \left({\beta}\right) \Gamma \left({\alpha + \beta}\right)}
	| c = Gamma Difference Equation
}}
{{eqn	| r = \frac \alpha {\alpha + \beta}
}}
{{end-eqn}}
{{qed}}
Category:Expectation
Category:Beta Distribution
