{{eqn	| r = \frac {\beta^\alpha} {\beta^{\alpha + 1} \Gamma \left({\alpha}\right)} \int_0^\infty t^\alpha e^{-t} \rd t
}}
{{eqn	| r = \frac {\Gamma \left({\alpha + 1}\right)} {\beta \Gamma \left({\alpha}\right)} 
	| c = {{Defof|Gamma Function}}
}}
{{eqn	| r = \frac {\alpha \Gamma \left({\alpha}\right)} {\beta \Gamma \left({\alpha}\right)} 
	| c = Gamma Difference Equation
}}
{{eqn	| r = \frac \alpha \beta
}}
{{end-eqn}}
{{qed}}
