\section{Differential Entropy of Continuous Uniform Distribution}
Tags: Uniform Distribution, Differential Entropy, Continuous Uniform Distribution

\begin{theorem}
Let $X \sim \ContinuousUniform a b$ for some $a, b \in \R$, $a \ne b$, where $\operatorname U$ is the continuous uniform distribution. 
Then the differential entropy of $X$, $\map h X$, is given by: 
:$\map h X = \map \ln {b - a}$
\end{theorem}

\begin{proof}
From the definition of the continuous uniform distribution, $X$ has probability density function: 
:$\map {f_X} x = \begin{cases} \dfrac 1 {b - a} & a \le x \le b \\ 0 & \text{otherwise} \end{cases}$
From the definition of differential entropy: 
:$\ds \map h X = - \int_{-\infty}^\infty \map {f_X} x \map \ln {\map {f_X} x} \rd x$
So: 
{{begin-eqn}}
{{eqn	| l = \map h X
	| r = -\int_a^b \frac 1 {b - a} \map \ln {\frac 1 {b - a} } \rd x
}}
{{eqn	| r = \frac {\map \ln {b - a} } {b - a} \int_a^b \rd x
	| c = Logarithm of Reciprocal
}}
{{eqn	| r = \frac {\map \ln {b - a} } {b - a} \sqbrk x_a^b 
	| c = Primitive of Constant, Fundamental Theorem of Calculus
}}
{{eqn	| r = \frac {\paren {b - a} \map \ln {b - a} } {b - a}
}}
{{eqn	| r = \map \ln {b - a}
}}
{{end-eqn}}
{{qed}}
Category:Continuous Uniform Distribution
Category:Differential Entropy
\end{proof}

\section{Differential Entropy of Exponential Distribution}
Tags: Exponential Distribution, Differential Entropy

\begin{theorem}
Let $X$ be a continuous random variable of the exponential distribution with parameter $\beta$ for some $\beta \in \R_{> 0}$. 
Then the differential entropy of $X$, $\map h X$, is given by: 
:$\map h X = 1 + \map \ln \beta$
\end{theorem}

\begin{proof}
From the definition of the exponential distribution, $X$ has probability density function:
:$\map {f_X} x = \dfrac 1 \beta e^{-\frac x \beta}$
From the definition of differential entropy: 
:$\ds \map h X = -\int_0^\infty \map {f_X} x \map \ln {\map {f_X} x} \rd x$
So:
{{begin-eqn}}
{{eqn	| l = \map h X
	| r = -\frac 1 \beta \int_0^\infty e^{-\frac x \beta} \map \ln {\frac 1 \beta e^{-\frac x \beta} } \rd x
}}
{{eqn	| r = \frac 1 \beta \int_0^\infty e^{-\frac x \beta} \map \ln {\beta e^{\frac x \beta} } \rd x
	| c = Reciprocal of Logarithm
}}
{{eqn	| r = \frac {\map \ln \beta} \beta \int_0^\infty e^{-\frac x \beta} \rd x + \frac 1 {\beta^2} \int_0^\infty x e^{-\frac x \beta} \rd x
	| c = Logarithm of Product, {{Defof|Natural Logarithm}}
}}
{{eqn	| r = \frac {\map \ln \beta} \beta \sqbrk {-\beta e^{-\frac x \beta} }_0^\infty + \frac 1 {\beta^2} \paren {\sqbrk {-\beta x e^{-\frac x \beta} }_0^\infty + \beta \int_0^\infty e^{-\frac x \beta} \rd x}
	| c = Primitive of Exponential Function, Integration by Parts
}}
{{eqn	| r = \frac {\beta \map \ln \beta} \beta + \frac 1 \beta \int_0^\infty e^{-\frac x \beta} \rd x
	| c = Exponential Tends to Zero and Infinity, Limit at Infinity of Polynomial over Real Exponential
}}
{{eqn	| r = \map \ln \beta + \frac 1 \beta \sqbrk {-\beta e^{-\frac x \beta} }_0^\infty
	| c = Primitive of Exponential Function
}}
{{eqn	| r = \map \ln \beta + \frac \beta \beta
	| c = Exponential Tends to Zero and Infinity, Exponential of Zero
}}
{{eqn	| r = 1 + \map \ln \beta
}}
{{end-eqn}}
{{qed}}
Category:Differential Entropy
Category:Exponential Distribution
\end{proof}

\section{Differential Entropy of Gaussian Distribution}
Tags: Gaussian Distribution, Differential Entropy

\begin{theorem}
Let $X \sim \Gaussian \mu {\sigma^2}$ for some $\mu \in \R, \sigma \in \R_{> 0}$, where $N$ is the Gaussian distribution.
Then the differential entropy $\map h X$ of $X$ is given by: 
:$\map h X = \map \ln {\sigma \sqrt {2 \pi} } + \dfrac 1 2$
\end{theorem}

\begin{proof}
From the definition of the Gaussian distribution, $X$ has probability density function:
:$\map {f_X} x = \dfrac 1 {\sigma \sqrt {2 \pi} } \, \map \exp {-\dfrac {\paren {x - \mu}^2} {2 \sigma^2} }$
From the definition of differential entropy: 
:$\ds \map h X = -\int_{-\infty}^\infty \map {f_X} x \ln \map {f_X} x \rd x$
So:
{{begin-eqn}}
{{eqn	| l = \map h X
	| r = - \frac 1 {\sigma \sqrt{2 \pi} } \int_{-\infty}^\infty \map \exp {-\frac {\paren {x - \mu}^2} {2 \sigma^2} } \map \ln {\frac 1 {\sigma \sqrt {2 \pi} } \map \exp {-\frac {\paren {x - \mu}^2} {2 \sigma^2} } } \rd x
}}
{{eqn	| r = \frac 1 {\sigma \sqrt {2 \pi} } \int_{-\infty}^\infty \map \exp {-\frac {\paren {x - \mu}^2} {2 \sigma^2} } \map \ln {\sigma \sqrt {2 \pi} \, \map \exp {\frac {\paren {x - \mu}^2} {2 \sigma^2} } } \rd x
	| c = Logarithm of Reciprocal
}}
{{eqn	| r = \frac {\sqrt 2 \sigma} { \sigma \sqrt {2 \pi} } \int_{-\infty}^\infty \map \exp {-t^2} \map \ln {\sigma \sqrt {2 \pi} \, \map \exp {t^2} } \rd t
	| c = substituting $t = \dfrac {x - \mu} {\sqrt 2 \sigma}$
}}
{{eqn	| r = \frac 1 {\sqrt \pi} \int_{-\infty}^\infty \paren {\map \ln {\sigma \sqrt {2 \pi} } + \map \ln {\map \exp {t^2} } } \, \map \exp {-t^2} \rd t
	| c = Sum of Logarithms
}}
{{eqn	| r = \frac {\map \ln {\sigma \sqrt {2 \pi} } } {\sqrt \pi} \int_{-\infty}^\infty \map \exp {-t^2} \rd t + \frac 1 {\sqrt \pi} \int_{-\infty}^\infty t^2 \map \exp {-t^2} \rd t
}}
{{eqn	| r = \frac {\sqrt \pi \, \map \ln {\sigma \sqrt {2 \pi} } } {\sqrt \pi} + \frac 1 {\sqrt \pi} \paren {\sqbrk {-\frac t 2 \, \map \exp {-t^2} }_{-\infty}^\infty + \frac 1 2 \int_{-\infty}^\infty \map \exp {-t^2} \rd t}
	| c = Gaussian Integral, Integration by Parts, Fundamental Theorem of Calculus
}}
{{eqn	| r = \map \ln {\sigma \sqrt {2 \pi} } + \frac 1 {2 \sqrt \pi} \int_{-\infty}^\infty \map \exp {-t^2} \rd t
	| c = Exponential Tends to Zero and Infinity
}}
{{eqn	| r = \map \ln {\sigma \sqrt {2 \pi} } + \frac {\sqrt \pi} {2 \sqrt \pi}
	| c = Gaussian Integral
}}
{{eqn	| r = \map \ln {\sigma \sqrt {2 \pi} } + \frac 1 2
}}
{{end-eqn}}
{{qed}}
Category:Gaussian Distribution
Category:Differential Entropy
\end{proof}

\section{Central Moment of Exponential Distribution}
Tags: Exponential Distribution, Central Moment, Central Moments

\begin{theorem}
Let $X$ be a continuous random variable of the exponential distribution with parameter $\beta$ for some $\beta \in \R_{> 0}$
Let $n$ be a strictly positive integer. 
Then the $n$th central moment $\mu_n$ of $X$ is given by: 
:$\ds \mu_n = n! \beta^n \sum_{k \mathop = 0}^n \frac {\paren {-1}^k} {k!}$
\end{theorem}

\begin{proof}
From definition of central moment we have:
:$\mu_n = \expect {\paren {x - \mu}^n}$
By Expectation of Exponential Distribution we have:
:$\mu = \beta$
So: 
{{begin-eqn}}
{{eqn	| l = \mu_2
	| r = \expect {\sum_{k \mathop = 0}^n \binom n k X^{n - k} \paren {-\beta}^k}
	| c = Binomial Theorem
}}
{{eqn	| r = \sum_{k \mathop = 0}^n \binom n k \paren {-\beta}^k \expect {X^{n - k} }
	| c = Linearity of Expectation Function
}}
{{eqn	| r = \sum_{k \mathop = 0}^n \beta^k \binom n k \paren {-1}^k \paren {\paren {n - k}! \beta^{n - k} }
	| c = Raw Moment of Exponential Distribution
}}
{{eqn	| r = \sum_{k \mathop = 0}^n \beta^n \paren {\frac {n!} {k! \paren {n - k}!} } \paren {-1}^k \paren {n - k}!
        | c = {{Defof|Binomial Coefficient}}
}}
{{eqn	| r = n! \beta^n \sum_{k \mathop = 0}^n \frac {\paren {-1}^k} {k!}
}}
{{end-eqn}}
{{qed}}
Category:Exponential Distribution
Category:Central Moments
\end{proof}

\section{Power of Random Variable with Continuous Uniform Distribution has Beta Distribution}
Tags: Beta Distribution, Continuous Uniform Distribution

\begin{theorem}
Let $X \sim \ContinuousUniform 0 1$ where $\ContinuousUniform 0 1$ is the continuous uniform distribution on $\closedint 0 1$.
Let $n$ be a positive real number. 
Then:
:$X^n \sim \BetaDist {\dfrac 1 n} 1$
where $\operatorname {Beta}$ is the beta distribution.
\end{theorem}

\begin{proof}
Let:
:$Y \sim \BetaDist {\dfrac 1 n} 1$
We aim to show that: 
:$\map \Pr {Y < x^n} = \map \Pr {X < x}$
for all $x \in \closedint 0 1$. 
We have:
{{begin-eqn}}
{{eqn	| l = \map \Pr {Y < x^n}
	| r = \int_0^{x^n} \frac 1 {\map \Beta {\frac 1 n, 1} } u^{\frac 1 n - 1} \paren {1 - u}^{1 - 1} \rd u
	| c = {{Defof|Beta Distribution}}
}}
{{eqn	| r = \frac {\map \Gamma {\frac 1 n + 1} } {\map \Gamma {\frac 1 n} \map \Gamma 1} \intlimits {n u^{\frac 1 n} } 0 {x^n}
	| c = {{Defof|Gamma Function}}, Primitive of Power
}}
{{eqn	| r = \frac n n x
	| c = Gamma Difference Equation
}}
{{eqn	| r = x
}}
{{eqn	| r = \frac 1 {1 - 0} \int_0^x \rd u
	| c = Primitive of Constant
}}
{{eqn	| r = \map \Pr {X < x}
	| c = {{Defof|Continuous Uniform Distribution}}
}}
{{end-eqn}}
{{qed}}
Category:Continuous Uniform Distribution
Category:Beta Distribution
\end{proof}

\section{Raw Moment of Exponential Distribution}
Tags: Exponential Distribution, Raw Moment, Raw Moments

\begin{theorem}
Let $X$ be a continuous random variable of the exponential distribution with parameter $\beta$ for some $\beta \in \R_{>0}$.
Let $n$ be a strictly positive integer. 
Then the $n$th raw moment of $X$ is given by: 
:$\expect {X^n} = n! \beta^n$
\end{theorem}

\begin{proof}
From Moment Generating Function of Exponential Distribution, the moment generating function of $X$ is given by:
:$\map {M_X} t = \dfrac 1 {1 - \beta t}$
By Moment in terms of Moment Generating Function:
:$\expect {X^n} = \map {M^{\paren n}_X} 0$
We have: 
{{begin-eqn}}
{{eqn	| l = \map {M^{\paren n}_X} t
	| r = \frac {\d^n} {\d t^n} \paren {\frac 1 {1 - \beta t} }
}}
{{eqn	| r = -\frac 1 \beta \frac {\d^n} {\d t^n} \paren {\frac 1 {t - \frac 1 \beta} }
}}
{{eqn	| r = -\frac {\paren {-1}^n n!} {\beta \paren {t - \frac 1 \beta}^{n + 1} }
	| c = Nth Derivative of Reciprocal of Mth Power: Corollary, Chain Rule for Derivatives
}}
{{eqn	| r = \frac {\paren {-1}^{n + 1} n!} {\frac \beta {\beta^{n + 1} } \paren {\beta t - 1}^{n + 1} }
}}
{{eqn	| r = \frac {\paren {-1}^{n + 1} n! \beta^n} {\paren {\beta t - 1}^{n + 1} } 
}}
{{end-eqn}}
Setting $t = 0$ gives:
{{begin-eqn}}
{{eqn	| l = \expect {X^n}
	| r = \frac {\paren {-1}^{n + 1} n! \beta^n} {\paren {-1}^{n + 1} }
}}
{{eqn	| r = n! \beta^n
}}
{{end-eqn}}
{{qed}}
Category:Exponential Distribution
Category:Raw Moments
\end{proof}

\section{Skewness of Continuous Uniform Distribution}
Tags: Skewness, Continuous Uniform Distribution

\begin{theorem}
Let $X$ be a continuous random variable which is uniformly distributed on a closed real interval $\closedint a b$. 
Then the skewness $\gamma_1$ of $X$ is equal to $0$.
\end{theorem}

\begin{proof}
From the definition of skewness: 
:$\gamma_1 = \expect {\paren {\dfrac {X - \mu} \sigma}^3}$
where: 
:$\mu$ is the mean of $X$
:$\sigma$ is the standard deviation of $X$. 
From the definition of the continuous uniform distribution, $X$ has probability density function:
:$\map {f_X} x = \dfrac 1 {b - a}$
So, from Expectation of Function of Continuous Random Variable:
:$\ds \gamma_1 = \expect {\paren {\dfrac {X - \mu} \sigma}^3} = \frac 1 {\paren {b - a} \sigma^3} \int_a^b \paren {x - \mu}^3 \rd x$
Then: 
{{begin-eqn}}
{{eqn	| l = \frac 1 {\paren {b - a} \sigma^3} \int_a^b \paren {x - \mu}^3 \rd x
	| r = \frac 1 {\paren {b - a} \sigma^3} \int_a^b \paren {x - \frac {a + b} 2}^3 \rd x
	| c = Expectation of Continuous Uniform Distribution
}}
{{eqn	| r = \frac 1 {\paren {b - a} \sigma^3} \int_{a - \frac {a + b} 2}^{b - \frac {a + b} 2} u^3 \rd u
	| c = substituting $u = x - \dfrac {a + b} 2$
}}
{{eqn	| r = \frac 1 {\paren {b - a} \sigma^3} \int_{-\frac {b - a} 2}^{\frac {b - a} 2} u^3 \rd u
}}
{{end-eqn}}
We have: 
:$\paren {-u}^3 = -u^3$
so we can see the integrand is odd. 
So, by Definite Integral of Odd Function: 
:$\ds \gamma_1 = \frac 1 {\paren {b - a} \sigma^3} \int_{-\frac {b - a} 2}^{\frac {b - a} 2} u^3 \rd u = 0$
{{qed}}
Category:Skewness
Category:Continuous Uniform Distribution
\end{proof}

\section{Skewness of Exponential Distribution}
Tags: Exponential Distribution, Skewness

\begin{theorem}
Let $X$ be a continuous random variable of the exponential distribution with parameter $\beta$ for some $\beta \in \R_{> 0}$
Then the skewness $\gamma_1$ of $X$ is equal to $2$.
\end{theorem}

\begin{proof}
From Skewness in terms of Non-Central Moments, we have: 
:$\gamma_1 = \dfrac {\expect {X^3} - 3 \mu \sigma^2 - \mu^3} {\sigma^3}$
where: 
:$\mu$ is the expectation of $X$. 
:$\sigma$ is the standard deviation of $X$.
By Expectation of Exponential Distribution we have: 
:$\mu = \beta$ 
By Variance of Exponential Distribution we have: 
:$\sigma = \beta$ 
By Raw Moment of Exponential Distribution we also have: 
:$\expect {X^3} = 3! \beta^3 = 6 \beta^3$
So: 
{{begin-eqn}}
{{eqn	| l = \gamma_1
	| r = \frac {6 \beta^3 - 3\beta^3 - \beta^3} {\beta^3}
}}
{{eqn	| r = \frac {2 \beta^3} {\beta^3}
}}
{{eqn	| r = 2
}}
{{end-eqn}}
{{qed}}
Category:Skewness
Category:Exponential Distribution
\end{proof}

\section{Standard Continuous Uniform Distribution in terms of Exponential Distribution}
Tags: Exponential Distribution, Continuous Uniform Distribution

\begin{theorem}
Let $X$ and $Y$ be independent random variables.
Let $\beta$ be a strictly positive real number.
Let $X$ and $Y$ be random samples from the exponential distribution with parameter $\beta$. 
Then:
:$\dfrac X {X + Y} \sim \operatorname U \openint 0 1$
where $\operatorname U \openint 0 1$ is the uniform distribution on $\openint 0 1$.
\end{theorem}

\begin{proof}
Note that the support of $\operatorname U \openint 0 1$ is $\openint 0 1$.
It is therefore sufficient to show that for $0 < z < 1$: 
:$\map \Pr {\dfrac X {X + Y} \le z} = z$
Note that if $x, y > 0$ then: 
:$0 < \dfrac x {x + y} < 1$
Note also that: 
:$\dfrac x {x + y} \le z$ 
with $0 < z < 1$ is equivalent to: 
:$x \le z x + z y$
which is in turn equivalent to: 
:$\paren {1 - z} x \le z y$
That is: 
:$x \le \dfrac z {1 - z} y$
We therefore have: 
:$\map \Pr {\dfrac X {X + Y} \le z} = \map \Pr {X \le \dfrac z {1 - z} Y}$
Let $f_{X, Y}$ be the joint probability density function of $X$ and $Y$. 
Let $f_X$ and $f_Y$ be the probability density function of $X$ and $Y$ respectively. 
From Condition for Independence from Joint Probability Density Function, we have for each $x, y \in \R_{> 0}$:
:$\map {f_{X, Y} } {x, y} = \map {f_X} x \map {f_Y} y$
We therefore have: 
{{begin-eqn}}
{{eqn	| l = \map \Pr {\dfrac X {X + Y} \le z}
	| r = \map \Pr {X \le \frac z {1 - z} Y}
}}
{{eqn	| r = \int_0^\infty \int_0^{\frac z {1 - z} y} \map {f_{X, Y} } {x, y} \rd x \rd y
}}
{{eqn	| r = \int_0^\infty \int_0^{\frac z {1 - z} y} \map {f_X} x \map {f_Y} y \rd x \rd y
}}
{{eqn	| r = \int_0^\infty \frac 1 \beta \map \exp {-\frac y \beta} \paren {\int_0^{\frac z {1 - z} y} \frac 1 \beta \map \exp {-\frac x \beta} \rd x} \rd y
	| c = {{Defof|Exponential Distribution}}
}}
{{eqn	| r = \int_0^\infty \frac 1 \beta \map \exp {-\frac y \beta} \intlimits {-\map \exp {-\frac x \beta} } 0 {\frac z {1 - z} y} \rd y
	| c = Primitive of Exponential of $a x$
}}
{{eqn	| r = \int_0^\infty \frac 1 \beta \map \exp {-\frac y \beta} \paren {1 - \map \exp {-\frac z {\beta \paren {1 - z} } y} } \rd y
	| c = Exponential of Zero
}}
{{eqn	| r = 1 - \frac 1 \beta \int_0^\infty \map \exp {-y \paren {\frac z {\beta \paren {1 - z} } + \frac 1 \beta} } \rd y
}}
{{eqn	| r = 1 - \frac 1 \beta \int_0^\infty \map \exp {-\frac y {\beta \paren {1 - z} } } \rd y
}}
{{eqn	| r = 1 + \frac 1 \beta \intlimits {\beta \paren {1 - z} \map \exp {-\frac y {\beta \paren {1 - z} } } } 0 \infty
	| c = Primitive of Exponential of $a x$
}}
{{eqn	| r = 1 + \frac 1 \beta \paren {0 - \beta \paren {1 - z} }
	| c = Exponential Tends to Zero and Infinity, Exponential of Zero
}}
{{eqn	| r = 1 - \paren {1 - z}
}}
{{eqn	| r = z
}}
{{end-eqn}}
{{qed}}
Category:Continuous Uniform Distribution
Category:Exponential Distribution
\end{proof}

\section{Variance of Beta Distribution}
Tags: Beta Distribution, Variance of Beta Distribution, Variance

\begin{theorem}
Let $X \sim \map \Beta {\alpha, \beta}$ for some $\alpha, \beta > 0$, where $\Beta$ is the Beta distribution. 
Then:
:$\var X = \dfrac {\alpha \beta} {\paren {\alpha + \beta}^2 \paren {\alpha + \beta + 1} }$
\end{theorem}

\begin{proof}
From the definition of the Beta distribution, $X$ has probability density function:
:$\map {f_X} x = \dfrac {x^{\alpha - 1} \paren {1 - x}^{\beta - 1} } {\map \Beta {\alpha, \beta} }$
From Variance as Expectation of Square minus Square of Expectation: 
:$\displaystyle \var X = \int_0^1 x^2 \map {f_X} X \rd x - \paren {\expect X}^2$
So: 
{{begin-eqn}}
{{eqn	| l = \var X
	| r = \frac 1 {\map \Beta {\alpha, \beta} } \int_0^1 x^{\alpha + 1} \paren {1 - x}^{\beta - 1} \rd x - \frac {\alpha^2} {\paren {\alpha + \beta}^2}
	| c = Expectation of Beta Distribution
}}
{{eqn	| r = \frac {\map \Beta {\alpha + 2, \beta} } {\map \Beta {\alpha, \beta} } - \frac {\alpha^2} {\paren {\alpha + \beta}^2}
	| c = {{Defof|Beta Function|index = 1}}
}}
{{eqn	| r = \frac {\map \Gamma {\alpha + 2} \, \map \Gamma \beta} {\map \Gamma {\alpha + \beta + 2} } \cdot \frac {\map \Gamma {\alpha + \beta} } {\map \Gamma \alpha \, \map \Gamma \beta} - \frac {\alpha^2} {\paren {\alpha + \beta}^2}
	| c = {{Defof|Beta Function|index = 3}}
}}
{{eqn	| r = \frac {\alpha \paren {\alpha + 1} } {\paren {\alpha + \beta} \paren {\alpha + \beta + 1} } \cdot \frac {\map \Gamma \alpha \, \map \Gamma \beta \, \map \Gamma {\alpha + \beta} } {\map \Gamma \alpha \, \map \Gamma \beta \, \map \Gamma {\alpha + \beta} } - \frac {\alpha^2} {\paren {\alpha + \beta}^2}
	| c = Gamma Difference Equation
}}
{{eqn	| r = \frac {\paren {\alpha^2 + \alpha} \paren {\alpha + \beta} } {\paren {\alpha + \beta}^2 \paren {\alpha + \beta + 1} } - \frac {\alpha^2 \paren {\alpha + \beta + 1} } {\paren {\alpha + \beta}^2 \paren {\alpha + \beta + 1} }
}}
{{eqn	| r = \frac {\alpha ^3 + \alpha^2 \beta + \alpha^2 + \alpha \beta - \alpha^3 - \alpha^2 \beta - \alpha^2} {\paren {\alpha + \beta}^2 \paren {\alpha + \beta + 1} }
}}
{{eqn	| r = \frac {\alpha \beta} {\paren {\alpha + \beta}^2 \paren {\alpha + \beta + 1} }
}}
{{end-eqn}}
{{qed}}
Category:Variance
Category:Beta Distribution
