You can also use a [ ROS2 launch file
](https://roboticsbackend.com/ros2-launch-file-example/) instead of adding all
your params manually in the terminal (additional improvement: you can also [
set all your params in a YAML config file
](https://roboticsbackend.com/ros2-yaml-params/) ).

def set_param(param, value, verbose=False):
    """
    Set param on the ROS parameter server using a YAML value.

    @param param: parameter name
    @type  param: str
    @param value: yaml-encoded value
    @type  value: str
    """
    set_param_raw(param, yaml.load(value), verbose=verbose)

def dump_params(filename, param, verbose=False):
    """
    Download a parameter tree from the Parameter Server and store in a yaml file
    @param filename: name of file to save YAML representation
    @type  filename: str
    @param param: name of parameter/namespace to dump
    @type  param: str
    @param verbose: print verbose output for debugging
    @type  verbose: bool
    """
    tree = get_param(param)
    if verbose:
        print_params(tree, param)
    f = open(filename, 'w')
    try:
        yaml.dump(tree, f)
    finally:
        f.close()

def delete_param(param, verbose=False):
    """
    Delete a parameter from the Parameter Server
    @param param: parameter name
    @type  param: str
    @param verbose: print verbose output for debugging
    @type  verbose: bool
    """
    try:
        if param == GLOBALNS:
            # not allowed to delete the root of the tree as it must always
            # have a value. the equivalent command is setting the root to an
            # empty dictionary
            _succeed(get_param_server().setParam(_get_caller_id(), GLOBALNS, {})) 
            if verbose:
                print "deleted ENTIRE parameter server"
        else:
            _succeed(get_param_server().deleteParam(_get_caller_id(), param))
            if verbose:
                print "deleted parameter [%s]"%param
    except socket.error:
        raise ROSParamIOException("Unable to communicate with master!")

# LOAD/SET

# TODO: break this into separate routines, has gotten too ugly to multiplex
def _rosparam_cmd_set_load(cmd, argv):
    """
    Process command line for rosparam set/load, e.g.::
      rosparam load file.yaml [namespace]
      rosparam set param value
    @param cmd: command name
    @type  cmd: str
    @param argv: command-line args
    @type  argv: str    
    """
    if cmd == 'load':
        parser = OptionParser(usage="usage: %prog load [options] file [namespace]", prog=NAME)
    elif cmd == 'set':
        parser = OptionParser(usage="usage: %prog set [options] parameter value", prog=NAME)
        parser.add_option("-t", "--textfile", dest="text_file", default=None,
                          metavar="TEXT_FILE", help="set parameters to contents of text file")
        parser.add_option("-b", "--binfile", dest="bin_file", default=None,
                          metavar="BINARY_FILE", help="set parameters to contents of binary file")

def set_param_raw(param, value, verbose=False):
    """
    Set param on the Parameter Server. Unlike L{set_param()}, this
    takes in a Python value to set instead of YAML.

    @param param: parameter name
    @type  param: str
    @param value XmlRpcLegalValue: value to upload
    @type  value: XmlRpcLegalValue
    """
    if type(value) == dict:
        # #1098 changing dictionary behavior to be an update, rather
        # than replace behavior.
        for k, v in value.iteritems():
            # dictionary keys must be non-unicode strings
            if isinstance(k, str):
                set_param_raw(ns_join(param, k), v, verbose=verbose)
            else:
                raise ROSParamException("YAML dictionaries must have string keys. Invalid dictionary is:\n%s"%value)
    else:
        if type(value) == long:
            if value > sys.maxint:
                raise ROSParamException("Overflow: Parameter Server integers must be 32-bit signed integers:\n\t-%s <= value <= %s"%(sys.maxint-1, sys.maxint))

        try:
            _succeed(get_param_server().setParam(_get_caller_id(), param, value))
        except socket.error:
            raise ROSParamIOException("Unable to communicate with master!")
        if verbose:
            print "set parameter [%s] to [%s]"%(param, value)

Let $\alpha,$ $\beta,$ and $\gamma$ be three real numbers.  Suppose that
\begin{align*}
\cos \alpha + \cos \beta + \cos \gamma &= 1, \\
\sin \alpha + \sin \beta + \sin \gamma &= 1.
\end{align*}Then the minimum value of $\cos \alpha$ can be expressed in the form $-\frac{p + \sqrt{q}}{r},$ where $p,$ $q,$ and $r$ are positive integers, and $q$ is not divisible by the square of a prime.  Find $p + q + r.$
Let $a = e^{i \alpha},$ $b = e^{i \beta},$ and $c = e^{i \gamma}.$  Then
\begin{align*}
a + b + c &= e^{i \alpha} + e^{i \beta} + e^{i \gamma} \\
&= \cos \alpha + i \sin \alpha + \cos \beta + i \sin \beta + \cos \gamma + i \sin \gamma \\
&= (\cos \alpha + \cos \beta + \cos \gamma) + i (\sin \alpha + \sin \beta + \sin \gamma) \\
&= 1 + i.
\end{align*}Note that $|a| = |b| = |c| = 1.$  Then by the Triangle Inequality,
\[|a - (1 + i)| = |-b - c| \le |b| + |c| = 2.\]Thus, $a$ must lie in the disc centered at $1 + i$ with radius 2.  Also, $a$ must lie on the circle centered at 0 with radius 1.

[asy]
unitsize(1 cm);

filldraw(Circle((1,1),2),gray(0.7));

draw((-1.5,0)--(3.5,0));
draw((0,-1.5)--(0,3.5));
draw(Circle((0,0),1),red);
draw((1,1)--((1,1) + 2*dir(-20)));

label("$2$", (1,1) + dir(-20), S);

dot("$1 + i$", (1,1), N);
[/asy]

We compute the intersection points of the circle centered at 0 with radius 1, and the circle centered at $1 + i$ with radius 2.  Let $x + yi$ be an intersection point, so $x^2 + y^2 = 1$ and $(x - 1)^2 + (y - 1)^2 = 4.$  Subtracting these equations and simplifying, we get
\[x + y = -\frac{1}{2}.\]Then $y = -\frac{1}{2} - x.$  Substituting into $x^2 + y^2 = 1,$ we get
\[x^2 + \left( x + \frac{1}{2} \right)^2 = 1.\]This simplifies to $8x^2 + 4x - 3 = 0.$  Then by the quadratic formula,
\[x = \frac{-1 \pm \sqrt{7}}{4}.\]Thus, the intersection point in the second quadrant is
\[-\frac{1 + \sqrt{7}}{4} + \frac{-1 + \sqrt{7}}{4} i,\]so the minimum value of $\cos \alpha$ is $-\frac{1 + \sqrt{7}}{4}.$  Thus, $a + b + c = 1 + 7 + 4 = \boxed{12}.$

Equality occurs when $a = -\frac{1 + \sqrt{7}}{4} + \frac{-1 + \sqrt{7}}{4} i$ and $b = c = \frac{1 + i - a}{2}.$

Two parabolas have the same focus, namely the point $(3,-28).$  Their directrices are the $x$-axis and the $y$-axis, respectively.  Compute the slope of their common chord.
Let $P$ and $Q$ be the the intersection points of the two parabolas.  Then by definition of the parabola, the distance from $P$ to their common focus $F$ is equal to the distance from $P$ to the $x$-axis.  Also, the distance between $P$ to $F$ is equal to $P$ to the $y$-axis.  This means $P$ is equidistant to both the $x$-axis and $y$-axis, so $P$ must lie on the line $y = -x.$

[asy]
unitsize(0.15 cm);

pair F, P, Q;

real parab (real x) {
  return(-(x^2 - 6*x + 793)/56);
}

real upperparab(real x) {
  return(sqrt(3)*sqrt(2*x - 3) - 28);
}

real lowerparab(real x) {
  return(-sqrt(3)*sqrt(2*x - 3) - 28);
}

F = (3,-28);
P = (18.0385,-18.0385);
Q = (43.9615,-43.9615);

draw((-10,0)--(50,0));
draw((0,-50)--(0,10));
draw(graph(parab,-10,47),red);
draw(graph(upperparab,3/2,50),blue);
draw(graph(lowerparab,3/2,50),blue);
draw(F--P--(P.x,0));
draw(P--(0,P.y));
draw(F--Q--(Q.x,0));
draw(Q--(0,Q.y));
draw((-10,10)--(50,-50),dashed);

label("$F$", F, NW, UnFill);
label("$P$", P, NE, UnFill);
label("$Q$", Q, NE, UnFill);

dot(F);
[/asy]

By the same argument, $Q$ also lies on the line $y = -x.$  Therefore, the slope of $\overline{PQ}$ is $\boxed{-1}.$

Let $C_1$ and $C_2$ be circles defined by $(x-10)^2 + y^2 = 36$ and $(x+15)^2 + y^2 = 81$ respectively. What is the length of the shortest line segment $PQ$ that is tangent to $C_1$ at $P$ and to $C_2$ at $Q$?
Circle $C_1$ has center $(10,0)$ and radius 6.  Let $A = (10,0).$  Circle $C_2$ has center $(-15,0)$ and radius 9.  Let $B = (-15,0).$

[asy]
unitsize(0.2 cm);

pair A, B, D, P, Q, R;

A = (10,0);
B = (-15,0);
D = (0,0);
P = intersectionpoint(Circle(A,6),arc((A + D)/2, abs(A - D)/2, 180, 360));
Q = intersectionpoint(Circle(B,9),arc((B + D)/2, abs(B - D)/2, 0, 180));
R = extension(B,Q,A,A + P - Q);

draw(Circle(A,6));
draw(Circle(B,9));
draw(P--Q);
draw((-26,0)--(18,0));
draw(B--R--A);
draw(A--P);
draw(rightanglemark(B,Q,D,40));
draw(rightanglemark(A,P,D,40));
draw(rightanglemark(B,R,A,40));

dot("$A$", A, NE);
dot("$B$", B, S);
label("$D$", D, SW);
dot("$P$", P, SW);
dot("$Q$", Q, N);
label("$R$", R, N);
[/asy]

The shortest such segment $\overline{PQ}$ will be an internal common tangent of the two cirlces, and $\angle BQD = \angle APD = 90^\circ.$  Extend $\overline{BQ}$ past $Q$ to $R$ so that $QR = PA.$  Then $APQR$ is a rectangle.

We have that $BR = BQ + QR = BQ + PA = 9 + 6 = 15$ and $AB = 25.$  Then by Pythagoras on right triangle $ARB,$
\[AR = \sqrt{AB^2 - BR^2} = \sqrt{25^2 - 15^2} = 20.\]Therefore, $PQ = AR = \boxed{20}.$
